<template>
<div v-if="initializing" role="status">正在初始化单据… <el-button link type="primary" @click="cancelOpen">取消加载单据</el-button></div>
<div v-if="initializationError" role="alert">单据初始化失败，请重试 <el-button link type="primary" @click="retryOpen">重试单据</el-button><el-button link @click="cancelOpen">取消</el-button></div>
<el-dialog v-model="visible" :title="opening?'登记期初库存':'添加'+(kind==='OUT'?'出库':kind==='IN'?'入库':'还库')+'工单'" class="warehouse-dialog" :class="{'production-out-dialog':form.type==='PRODUCTION_OUT','process-raw-return-dialog':recovery,'multi-inbound-dialog':groupedWarehouse}" :width="form.type==='PRODUCTION_OUT'?'min(1188px,96vw)':'min(900px,94vw)'" top="5vh" :close-on-click-modal="false" :close-on-press-escape="!busy&&!uncertain" :show-close="!busy&&!uncertain">
 <p v-if="refreshFailed" role="status">更新检查失败，当前资料可能过期。</p><el-alert v-if="refreshError" :title="refreshError" type="warning" :closable="false"/><el-button v-if="needsReview&&!uncertain" @click="recheckDraft">重新核对候选</el-button><el-alert v-if="uncertain" title="提交结果未知，请重试原请求确认结果；全部输入已保留。" type="warning" :closable="false"/><el-button v-if="uncertain" type="primary" :loading="busy" @click="retrySubmission">重试原请求</el-button><el-form ref="headerForm" :model="headerModel" :rules="headerRules" scroll-to-error class="order-header-form" label-width="142px" label-position="left" :disabled="busy||loading||uncertain">
 <el-form-item label="单据编号"><el-input :model-value="inboundGroups.length>1?'保存后按仓库生成单号':form.orderNo" readonly/></el-form-item>
 <el-form-item label="工厂" prop="factoryId" :rules="[requiredRule('工厂',true,true),...([])]"><el-select :model-value="form.factoryId" :disabled="!admin" fit-input-width @change="changeFactory"><el-option v-for="o in factories" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item>
 <el-form-item prop="type" :rules="[requiredRule(kind==='OUT'?'出库类型':kind==='RET'?'还库类型':'入库类型',true,true),...([])]" :label="kind==='OUT'?'出库类型':kind==='RET'?'还库类型':'入库类型'"><el-select :model-value="form.type" fit-input-width @change="v=>groupedWarehouse?changeInboundContext('type',v):(form.type=v,typeChanged())"><el-option v-for="type in types" :key="type" :label="orderTypeNames[type]" :value="type"/></el-select></el-form-item>
 <el-form-item v-if="returning && batchReturning" label="对应出库工单" prop="sourceOrderId" :rules="[requiredRule('对应出库工单',true,true),...([])]"><el-select v-model="form.sourceOrderId" filterable clearable placeholder="请选择生产出库工单" fit-input-width @change="sourceOrderChanged"><el-option v-for="o in sourceOrders" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item>
 <template v-if="productionAllowed && !batchReturning"><el-form-item label="生产工单" prop="workOrderId" :rules="[requiredRule('生产工单',form.type==='PRODUCTION_OUT',true),...([])]"><el-select :model-value="form.workOrderId" clearable fit-input-width @change="v=>groupedWarehouse?changeInboundContext('workOrderId',v):(form.workOrderId=v,orderChanged())"><el-option v-for="o in orders" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item><el-form-item v-if="form.workOrderId" :label="rawTask?'原料明细':'产品明细'" prop="itemId" :rules="[requiredRule('产品明细',true,true),...([])]"><el-select :disabled="detailLoading" :model-value="itemId" fit-input-width @change="v=>groupedWarehouse?changeInboundContext('itemId',v):(itemId=v,itemChanged())"><el-option v-for="(o,i) in selectableItems" :key="o.id" :label="(o.materialSnapshot??o.snapshot)?.name+' '+(i+1)" :value="o.id"/></el-select></el-form-item><el-form-item v-if="itemId" label="工序" prop="processId" :rules="[requiredRule('工序',true,true),...([])]"><el-select :disabled="detailLoading" :model-value="processId" fit-input-width @change="v=>groupedWarehouse?changeInboundContext('processId',v):(processId=v,processChanged())"><el-option v-for="o in steps" :key="o.processId" :label="o.processName" :value="o.processId"/></el-select></el-form-item></template>
 <el-alert v-if="recovery&&itemId&&!detailLoading&&!steps.length" type="warning" :closable="false" title="当前产品没有可登记加工余料的工序：须有未结算批次、有效半成品领料及产出，且领料扣除产出和已还料后仍有额度。若有实物余料，请核对产出重量。"/><el-form-item v-if="form.type==='SEMI_RETURN'||recovery" class="wide-form-item" label="还库原因" prop="reason" :rules="[requiredRule('还库原因',true,false),...([])]"><el-input v-model="form.reason" type="textarea" maxlength="500" :placeholder="recovery?'说明加工粉末、边角料的回收情况':'说明未加工半成品还库原因；还库不会自动释放'"/></el-form-item>
 <el-form-item prop="orderDate" :rules="[requiredRule(kind==='OUT'?'出库日期':kind==='RET'?'还库日期':'入库日期',true,true),...([])]" :label="kind==='OUT'?'出库日期':kind==='RET'?'还库日期':'入库日期'"><el-date-picker v-model="form.orderDate" type="date" value-format="YYYY-MM-DD" :teleported="true"/></el-form-item>
 <el-form-item v-if="groupedWarehouse" label="仓库/库房" prop="warehouseId" :rules="[requiredRule('仓库/库房',true,true)]"><el-select :model-value="inboundGroups.map(g=>g.warehouseId)" multiple fit-input-width @change="changeInboundWarehouses"><el-option v-for="o in warehouses" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item>
 <el-form-item v-else label="仓库/库房" prop="warehouseId" :rules="[requiredRule('仓库/库房',true,true),...([])]"><el-select v-model="form.warehouseId" :disabled="form.type==='SEMI_RETURN'&&!!form.sourceOrderId" fit-input-width @change="warehouseChanged"><el-option v-for="o in warehouses" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item>
 <el-form-item v-for="field in peopleFields" :key="field.key" :prop="field.key" :label="field.label"  :rules="[requiredRule(field.label,field.required&&commonPeopleRequired,true),...([fieldRule(v=>field.required&&commonPeopleRequired&&(!v||(Array.isArray(v)&&!v.length))?'请选择'+field.label:Array.isArray(v)&&v.length>20?'经办人最多20位':'','change')])]"><el-select v-model="form[field.key]" :multiple="field.key==='operatorIds'" filterable fit-input-width clearable popper-class="person-select-options" class="person-select" :class="{'person-selected':Array.isArray(form[field.key])?form[field.key].length>0:!!form[field.key]}"><el-option v-for="o in people" :key="o.id" :label="personLabel(o)" :value="o.id"/></el-select></el-form-item>
 <div v-if="form.type==='PRODUCTION_OUT'&&hasExternalSources" class="shared-entry-summary" role="status"><template v-if="activeSharedContext"><template v-if="hasWeightExternal">重量型半成品按库存及释放净重领用；参考件数不占用接入额度。本单外部领用净重：{{decimalText(externalWeight)}}g。</template><template v-if="hasPieceExternal">本工序可外部接入{{activeSharedContext.externalEntryCapacity}}件，本单已填{{sharedFilled}}件，剩余{{sharedRemaining}}件。</template><strong v-if="sharedRemaining!==undefined&&sharedRemaining<0n">已超出共享额度，请调整清单。</strong></template><template v-else>共享接入额度未就绪，请完成选择或刷新。</template><span>本单未提交不预占，保存时重新核对。</span></div>
 <div v-if="form.type==='PRODUCTION_OUT'&&form.workOrderId&&itemId&&processId&&form.warehouseId" class="stock-refresh"><el-button link type="primary" :disabled="busy||checkingStock||productionStockLoading||!form.workOrderId||!itemId||!processId||!form.warehouseId" @click="loadProductionStocks(false)">刷新额度</el-button></div>
 <template v-if="recovery"><el-form-item label="客户"><el-input :model-value="form.workOrderCustomer" readonly/></el-form-item><el-alert type="info" :closable="false" title="加工后的粉末、边角料按原材料还库并扣减本批次损耗，不恢复半成品件数；实际以称重为准。"/><p role="status">领料 {{recoveryContext?.issued??'—'}}g；产出 {{recoveryContext?.output??'—'}}g；已回收 {{recoveryContext?.process_returned??'—'}}g；本单待还 {{decimalText(recoveryFilled)}}g；剩余可登记 {{decimalText(recoveryRemaining)}}g <el-button link :disabled="busy||recoveryLoading" @click="loadRecovery()">刷新额度</el-button></p><p v-if="recoveryError" role="alert">{{recoveryError}}</p></template>
 <p v-if="recovery&&form.workOrderId&&itemId&&!steps.length&&!detailLoading" role="alert">当前产品没有可登记加工余料的工序：须已领用半成品、登记产出，批次未结算且仍有可还重量。</p>
 <section v-if="groupedWarehouse&&inboundGroups.length" class="inbound-warehouse-groups">
 <el-tabs :model-value="String(form.warehouseId)" @update:model-value="activateInboundGroup(String($event))"><el-tab-pane v-for="g in inboundGroups" :key="g.warehouseId" :name="g.warehouseId" :label="warehouseName(g.warehouseId)"/></el-tabs>
 <p class="inbound-group-summary">{{warehouseName(form.warehouseId)}}：明细 {{form.lines.length}} 条，净重合计 {{decimalText(inboundWeight)}} g<span v-if="groupedOutbound&&form.lines.some((l:Row)=>l.category!=='RAW')">，有效件数 {{outboundEffectiveQuantity}}，参考件数 {{outboundReferenceQuantity}}</span><span v-else-if="form.type!=='RAW_IN'&&form.lines.some((l:Row)=>l.category!=='RAW')">，{{weightOutput?'参考件数':'件数'}}合计 {{inboundQuantity}}</span></p>
 <p v-if="groupedOutbound" class="inbound-group-summary">全部仓库待领：{{allInboundLines.length}} 条，净重 {{decimalText(outboundTotalWeight)}} g；库存可领余额按各仓库存记录核对，外部接入额度由全部仓库共用。</p><p v-if="form.type==='PRODUCTION_OUT'&&groupedOutbound&&!productionStockLoading&&!productionStocks.length&&itemId&&processId" role="status">当前仓库没有符合本工单、工序要求的可领库存。</p><el-switch v-if="activeInboundGroup" :model-value="activeInboundGroup.separatePeople" active-text="单独设置人员" @change="toggleInboundPeople(Boolean($event))"/>
 <div v-if="activeInboundGroup?.separatePeople" class="inbound-people-grid"><el-form-item v-for="field in peopleFields" :key="field.key" :label="field.label" :error="inboundPeopleError(field.key)"><el-select v-model="activeInboundGroup.people[field.key]" :multiple="field.key==='operatorIds'" filterable clearable fit-input-width popper-class="person-select-options" class="person-select"><el-option v-for="o in people" :key="o.id" :label="personLabel(o)" :value="o.id"/></el-select></el-form-item></div>
 <p v-if="inboundError&&!uncertain" role="alert" class="inbound-error">{{inboundError}}</p>
 </section>
 <div class="line-toolbar"><span><span class="required-mark">*</span>物料清单</span><el-button class="blue" :disabled="uncertain||needsReview||dependenciesLoading||returnContextMissing||!form.factoryId||!form.warehouseId||form.type==='PRODUCTION_OUT'&&(!itemId||!processId)" @click="editLine()">添加</el-button><el-button class="orange" :disabled="uncertain||selected.length!==1" @click="editLine(selected[0])">编辑</el-button><el-button class="red" :disabled="uncertain||!selected.length" @click="removeLines">删除</el-button><el-button v-if="can('metal:warehouse-order:import')" class="blue" @click="download">模板下载</el-button><el-button v-if="can('metal:warehouse-order:import')" class="blue" :disabled="uncertain||needsReview||dependenciesLoading||returnContextMissing||!form.factoryId||!form.warehouseId" @click="fileRef?.click()">导入模板</el-button><input ref="fileRef" type="file" accept=".xlsx" hidden @change="importFile"/></div>
 <el-table :data="form.lines" :row-class-name="outboundRowClass" border @selection-change="selected=$event"><el-table-column type="selection" width="42"/><el-table-column v-for="c in lineColumns" :key="c.key" :label="c.label" :prop="c.key" :formatter="c.key==='receivingOrganization'?receivingOrganizationText:c.key==='quantity'?quantityText:decimalColumn" :min-width="c.width||90" :label-class-name="kind==='IN'&&!opening&&c.key==='netWeight'?'inbound-net-weight-heading':''"/><el-table-column label="操作" width="140" align="center"><template #default="{row}"><div class="material-line-actions"><el-button class="detail-edit-button" size="small" @click="editLine(row)">编辑</el-button><el-button class="detail-delete-button" size="small" @click="form.lines.splice(form.lines.indexOf(row),1)">删除</el-button></div></template></el-table-column></el-table>
 <el-tag v-if="productionAllowed&&form.workOrderId&&itemId&&processId&&filteredBatches.length&&filteredBatches.every((b:Row)=>b.completionPolicy==='LEGACY')" type="info">历史批次流程</el-tag>
 <section v-if="!singleBatch&&form.batchId&&['RAW_RETURN','SEMI_RETURN','PROCESS_RAW_RETURN','FINISHED_IN','SEMI_IN'].includes(form.type)" class="batch-settlement">
  <div class="settlement-controls">
   <el-form-item label="本批次结算" class="settlement-choice"><el-checkbox v-model="form.settle" :disabled="!can('metal:process-batch:settle')" @change="revealCompletedQuantity">全部领回料已登记，确认结算</el-checkbox></el-form-item>
   <div v-if="form.settle&&!weightOutput" ref="settlementQuantity" class="settlement-quantity"><el-form-item label="实际完成数量" prop="completedQuantity" :rules="[requiredRule('实际完成数量',true,false),...([])]"><el-input v-model="form.completedQuantity" @input="v=>completedQuantityInput=String(v)" inputmode="numeric" placeholder="填写总件数"><template #append>件</template></el-input></el-form-item></div>
  </div>
  <div class="settlement-notes"><p v-if="form.settle" class="settlement-help">实际完成数量须等于本批次所有有效半成品／成品入库明细的数量合计，且不能超过批次计划数量；不是单条入库明细数量。</p><p class="settlement-help">本批次的领料、原料还库、半成品还库和产出全部登记后再勾选。请确认未加工的半成品已还库。结算不会自动退回余料，新工单正常完成后的剩余半成品按策略另行自动释放，部分关闭及历史工单仍须单独确认。确认单据时将结算本批次，计算损耗并生成报工记录；尚需继续登记时不要勾选。</p></div>
 </section>
 <el-alert v-if="dualBatch&&(boundOutput||returning||recovery)" title="本批采用加工人员交接、指定库管独立验收；产出及全部余料须一次申报，不能在此重复建单。" type="info" :closable="false"/><el-button v-if="dualBatch&&(boundOutput||returning||recovery)&&can('metal:warehouse-order:handover')" type="primary" @click="openHandover">由本人提交整批加工交接</el-button><el-alert v-if="singleBatch&&boundOutput" title="每批只允许一次产出入库。入库成功后，请一次确认全部还料或无余料，再自动结算。按件产出的完成件数自动汇总；重量型产出按实测净重结算，参考件数不作为完成量。" type="info" :closable="false"/>
 <el-button v-if="singleBatch&&returning&&can('metal:warehouse-order:add')" type="primary" @click="openReturnConfirmation">去本批次全部还料确认</el-button>
 </el-form><template #footer><el-button :disabled="busy||uncertain" @click="visible=false">取消</el-button><el-button v-if="can('metal:warehouse-order:add')" type="primary" :loading="busy" :disabled="uncertain||needsReview||dependenciesLoading||returnContextMissing" @click="save">确认</el-button></template>
</el-dialog>
<el-dialog v-model="lineVisible" :close-on-press-escape="!checkingStock" :show-close="!checkingStock" :title="out && form.type==='PRODUCTION_OUT' ? '取物料明细' : '物料明细'" class="warehouse-line-dialog" width="min(620px,94vw)" :close-on-click-modal="false"><el-form ref="lineForm" :model="line" :rules="lineRules" scroll-to-error label-width="120px" :disabled="checkingStock||refreshingReturn||recoveryLoading">
<el-form-item v-if="opening" label="分类"><el-select v-model="line.category" @change="line.referenceId='' "><el-option label="原材料" value="RAW"/><el-option label="成品" value="FINISHED"/><el-option label="半成品" value="SEMI"/></el-select></el-form-item>
<p v-if="form.type==='PRODUCTION_OUT'&&line.releaseId&&sharedLineRemaining!==undefined" class="shared-entry-summary">排除当前编辑行后，本条剩余可接入{{sharedLineRemaining}}件。</p>
<el-form-item prop="choiceId" :rules="[requiredRule(recovery?'回收原材料':out?'库存物料':returning?'原出库明细':line.category==='RAW'?'原材料':line.category==='SEMI'?'半成品':'成品',true,true),...([])]" :label="recovery?'回收原材料':out?'库存物料':returning?'原出库明细':line.category==='RAW'?'原材料':line.category==='SEMI'?'半成品':'成品'"><el-select v-model="line.choiceId" :popper-class="out?'warehouse-stock-options':undefined" :disabled="boundOutput&&(dependenciesLoading||!selectedOutputItem)||form.type==='PRODUCTION_OUT'&&(!form.workOrderId||!itemId||!processId||productionStockLoading)" :placeholder="recovery?'请选择回收原材料':out?'请选择库存物料':returning?'请选择原出库明细':line.category==='RAW'?'请选择原材料':line.category==='SEMI'?'请选择半成品对应产品':'请选择成品对应产品'" filterable fit-input-width @change="choiceChanged"><el-option v-for="o in choices" :key="o.choiceKey||o.id" :label="materialChoiceLabel(o)" :value="o.choiceKey||o.id" :disabled="batchReturning&&!returnSourceUsable(o)" :aria-label="materialChoiceLabel(o)"><template v-if="out"><div class="stock-option-main">{{stockOptionMain(o)}}</div><div v-if="stockOptionDetail(o)" class="stock-option-detail">{{stockOptionDetail(o)}}</div></template><template v-else>{{materialChoiceLabel(o)}}</template></el-option></el-select><span v-if="boundOutput&&!selectedOutputItem" role="status">请先选择生产工单的产品明细</span></el-form-item>
<el-form-item v-if="rawCustomerEntry" label="客户完整资料"><CustomerSnapshot :snapshot="customers.find(c=>c.id===line.customerId)" :factory-owned="line.materialOwnership==='FACTORY'"/></el-form-item><el-form-item v-if="nativePowderEntry" label="铱粉来源" prop="powderOrigin" :rules="[requiredRule('铱粉来源',true,true)]"><el-select v-model="line.powderOrigin" aria-label="铱粉来源"><el-option label="原生粉" value="NATIVE"/><el-option label="回收粉" value="RECYCLED"/></el-select></el-form-item><el-form-item v-if="line.skipPermitId&&out" label="工艺跳步确认"><el-checkbox v-model="line.skipAcknowledged">依据许可跳过第{{(line.skippedSequences??[]).join('、')}}道，不生成跳过工序报工</el-checkbox></el-form-item>
 <el-form-item v-if="!out&&!returning&&line.category!=='RAW'&&!form.batchId" label="批次号" prop="batchNo"><el-input v-model="line.batchNo" placeholder="可不填，系统生成" maxlength="160"/></el-form-item><el-form-item v-if="line.category==='RAW'" :label="out && form.type==='PRODUCTION_OUT' ? '取毛重(g)' : '毛重(g)'" :prop="'grossWeight'" :error="weightError('grossWeight')"><BusinessDecimalInput v-model="line.grossWeight" inputmode="decimal" maxlength="21" placeholder="请输入数字，保留两位小数" @input="deriveNet"/></el-form-item><el-form-item v-if="line.category==='RAW'" :label="out && form.type==='PRODUCTION_OUT' ? '含杂质(g)' : '杂质(g)'" :prop="'impurity'" :error="weightError('impurity')"><BusinessDecimalInput v-model="line.impurity" inputmode="decimal" maxlength="21" placeholder="请输入数字，保留两位小数" @input="deriveNet"/></el-form-item><el-form-item :label="out && form.type==='PRODUCTION_OUT' ? '实测取净重(g)' : '实测净重(g)'" :prop="'netWeight'" :error="weightError('netWeight')" :rules="[requiredRule(out && form.type==='PRODUCTION_OUT' ? '实测取净重(g)' : '实测净重(g)',true,false),...([])]"><BusinessDecimalInput v-model="line.netWeight" inputmode="decimal" maxlength="21" placeholder="请输入数字，保留两位小数"/></el-form-item><el-form-item v-if="line.category!=='RAW'&&!lineWeight" label="数量(件)" prop="quantity" :rules="[requiredRule('数量(件)',true,false),...([])]"><el-input v-model="line.quantity" @input="v=>lineQuantityInput=String(v)" inputmode="numeric"/></el-form-item><el-form-item v-if="lineWeight" class="weight-reference-field" label="参考件数（选填）" prop="referenceQuantity"><el-input v-model="line.referenceQuantity" inputmode="numeric" placeholder="可不填，不参与加工额度计算"/><span class="field-help">按净重管理；参考件数仅作实物记录。</span></el-form-item><el-form-item v-if="line.category!=='RAW'" label="纯度(%)" prop="purity" :error="purityError()"><BusinessDecimalInput v-model="line.purity" :max="100" inputmode="decimal" placeholder="范围0～100，保留两位小数"/></el-form-item><el-form-item v-if="rawCustomerEntry" label="材料归属"><el-select v-model="line.materialOwnership" @chan