async function download(){const data=await request({url:'/metal/warehouse-order/template',params:(kind.value==='IN'&&(!opening.value||line.category==='RAW')||recovery.value||['RAW_RETURN','EXCHANGE_OUT'].includes(form.type))?{type:importType.value,batchBound:!!form.batchId,factoryId:form.factoryId}:undefined,responseType:'blob'});const url=URL.createObjectURL(data as unknown as Blob);const a=document.createElement('a');a.href=url;a.download='仓储物料模板.xlsx';a.click();URL.revokeObjectURL(url)}
// Production outbound preview and save both let the server bind the current OPEN batch; import must use the same context.
async function importFile(event:Event){if(returning.value&&batchReturning.value&&!form.sourceOrderId){ElMessage.error('请先选择对应出库工单');(event.target as HTMLInputElement).value='';return}const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file||dependenciesLoading.value||busy.value)return;const session=openEpoch,epoch=++optionEpoch;const warehouse=form.warehouseId;const outputContext=[form.factoryId,form.workOrderId,itemId.value,processId.value,form.type];const current=()=>!disposed&&formSessionCurrent()&&session===openEpoch&&epoch===optionEpoch&&warehouse===form.warehouseId&&outputContext.every((v,i)=>v===[form.factoryId,form.workOrderId,itemId.value,processId.value,form.type][i]);loading.value=true;try{const r=await importWarehouseLines(file,{...form,type:importType.value,itemId:itemId.value,processId:processId.value,...(groupedOutbound.value?{batchId:null,submissionDraft:outboundDraft()}: {})},current);if(!current())return;if(recovery.value&&!await validateRecovery((r as any).data))return;if((groupedWarehouse.value?allInboundLines.value.length:form.lines.length)+(r as any).data.length>1000){ElMessage.error('物料清单合计最多1000行，本次导入未追加');return}if(returning.value&&batchReturning.value&&(r as any).data.some((row:Row)=>!sources.value.some(o=>o.id===row.sourceLineId&&o.orderId===form.sourceOrderId))){ElMessage.error('导入物料必须来自所选出库工单');return}if(batchReturning.value&&!await validateRawReturns((r as any).data))return;if(out.value&&(r as any).data.some((row:Row)=>row.skipPermitId)){try{await ElMessageBox.confirm('导入包含工艺许可跳步领料；跳过工序不会生成报工。请确认本次工艺许可。','工艺跳步确认',{type:'warning',confirmButtonText:'确认跳步领料',cancelButtonText:'取消'})}catch{return}if(!current())return;for(const row of (r as any).data)if(row.skipPermitId)row.skipAcknowledged=true;}if(out.value&&!await validateOutgoingLines((r as any).data))return;if(!current())return;const productError=outputProductError((r as any).data,true);if(productError){ElMessage.error(productError);return}form.lines.push(...(r as any).data.map((row:Row)=>kind.value==='IN'&&!opening.value&&form.workOrderId&&row.category!=='RAW'?{...row,organization:form.workOrderCustomer??''}:row));ElMessage.success('已填充明细，确认后才会过账')}catch(error:any){if(current()&&groupedOutbound.value){loading.value=false;input.value='';outboundErrors.value=error?.fieldErrors??[];const index=Number(outboundErrors.value[0]?.field?.match(/^groups\[(\d+)\]/)?.[1]);const group=inboundGroups.value[index];if(group)activateInboundGroup(group.warehouseId);inboundError.value=userMessage(error?.message,'导入失败，请核对当前仓库物料后重试')}}finally{if(!disposed&&formSessionCurrent()&&session===openEpoch&&epoch===optionEpoch){loading.value=false;input.value=''}}}
function openReturnConfirmation(){const b=batches.value.find(b=>b.completionPolicy==='SINGLE_OUTPUT_RETURN'&&String(b.workOrderId)===String(form.workOrderId)&&String(b.itemId)===String(itemId.value)&&String(b.processId)===String(processId.value));if(!b)return;visible.value=false;emit('complete-batch',String(b.id))}
// Build after validation so refreshed batch versions and customer context are included.
function singleOrderPayload(){const data={...form,...(groupedWarehouse.value&&activeInboundGroup.value?.separatePeople?activeInboundGroup.value.people:{}),batchId:recovery.value?form.batchId:null,batchVersion:recovery.value?form.batchVersion:null,itemId:form.workOrderId?itemId.value:null,processId:form.workOrderId?processId.value:null,workOrderId:form.workOrderId||null,recipientId:(groupedWarehouse.value&&activeInboundGroup.value?.separatePeople?activeInboundGroup.value.people.recipientId:form.recipientId)||null,inspectorId:(groupedWarehouse.value&&activeInboundGroup.value?.separatePeople?activeInboundGroup.value.people.inspectorId:form.inspectorId)||null,reviewerId:(groupedWarehouse.value&&activeInboundGroup.value?.separatePeople?activeInboundGroup.value.people.reviewerId:form.reviewerId)||null,lines:form.lines.map((r:Row)=>({...r,grossWeight:r.grossWeight||null,impurity:r.impurity||null,purity:r.purity||null}))};return JSON.parse(JSON.stringify(data))}
async function save(){if(!formSessionCurrent()||busy.value||dependenciesLoading.value||uncertain.value||needsReview.value)return;if(dualBatch.value&&(boundOutput.value||returning.value||recovery.value)){ElMessage.warning('本批须由实际加工人员统一提交全部交接');return}if(singleBatch.value&&returning.value){openReturnConfirmation();return}const validationSession=openEpoch;if(!await headerForm.value?.validate().catch(()=>false)||validationSession!==openEpoch||!visible.value||!formSessionCurrent())return;if(groupedWarehouse.value&&!validateInboundDraft())return;if(groupedWarehouse.value&&inboundGroups.value.length>1){if(groupedOutbound.value)await saveOutboundGroups();else await saveInboundGroups();return}if(singleBatch.value)form.settle=false;if(form.settle)form.completedQuantity=Number(form.completedQuantity);const productError=outputProductError(form.lines);if(productError){ElMessage.error(productError);return}if(returning.value&&batchReturning.value&&(!form.sourceOrderId||form.lines.some((row:Row)=>!sources.value.some(o=>o.id===row.sourceLineId&&o.orderId===form.sourceOrderId)))){ElMessage.error('请选择对应出库工单，物料必须来自该单据');return}if((form.type==='SEMI_RETURN'||recovery.value)&&!String(form.reason??'').trim()){ElMessage.error(recovery.value?'请填写加工余料还库原因':'请填写半成品还库原因');return}if(!form.factoryId||!form.warehouseId||!form.orderDate||(form.type!=='PRODUCTION_OUT'&&!form.operatorIds?.length)||!(groupedOutbound.value&&activeInboundGroup.value?.separatePeople?activeInboundGroup.value.people.keeperId:form.keeperId)||!form.lines.length){ElMessage.error('请选择工厂、库房、日期、经办人、仓管员并添加物料');return}if((['PRODUCTION_OUT','RAW_RETURN','SEMI_RETURN','PROCESS_RAW_RETURN'].includes(form.type)||form.workOrderId)&&(!form.workOrderId||!itemId.value||!processId.value)){ElMessage.error('请选择生产工单、产品明细和工序');return}if(form.settle&&!weightOutput.value&&(!Number.isInteger(form.completedQuantity)||form.completedQuantity<1)){ElMessage.error('请填写正整数实际完成数量');return}const session=openEpoch;busy.value=true;try{const retrying=out.value&&singleOrderAttempts?.epoch===session&&singleOrderAttempts.bodies.has(JSON.stringify(singleOrderPayload()));if(recovery.value&&!await validateRecovery(form.lines,-1,true))return;if(form.type==='RAW_RETURN'&&!await validateRawReturns(form.lines,-1,true))return;/* Identical attempted requests must reach server replay before checking the stock they may already have consumed. */if(out.value&&!retrying&&!await validateOutgoingLines(form.lines,-1,true))return;if(disposed||session!==openEpoch)return;const payload=singleOrderPayload(),body=JSON.stringify(payload);if(singleOrderAttempts?.epoch!==session)singleOrderAttempts={epoch:session,bodies:new Set()};singleOrderAttempts.bodies.add(body);await postSubmission('/metal/'+(opening.value?'inventory/opening':'warehouse-order'),payload,'single')}catch(error){if(!disposed&&formSessionCurrent()&&session===openEpoch)applyFieldErrors(headerForm.value,error)}finally{if(!disposed&&formSessionCurrent()&&session===openEpoch)busy.value=false}}
async function postSubmission(url:string,payload:Row,kind:'single'|'inbound'|'outbound'){if(!formSessionCurrent())return;pendingSubmission={url,payload:JSON.parse(JSON.stringify(payload)),kind,completion:boundOutput.value};await retrySubmission()}
async function retrySubmission(){
 if(!pendingSubmission||!formSessionCurrent())return;const attempt=pendingSubmission,session=openEpoch,valid=()=>!disposed&&formSessionCurrent()&&visible.value&&session===openEpoch&&pendingSubmission===attempt;busy.value=true;inboundError.value='';
 try{const result:any=await request({url:attempt.url,method:'post',headers:{repeatSubmit:false},isContextCurrent:valid,data:attempt.payload});if(!valid())return;
  let completionId='';if(attempt.kind==='single'&&attempt.completion&&result.id){try{const posted=(await warehouseDetail('warehouse-order',String(result.id),false,valid)).data;if(!valid())return;if(posted.completionPolicy==='SINGLE_OUTPUT_RETURN')completionId=String(posted.batchId)}catch{if(valid())ElMessage.warning('入库已生效，请从单据详情继续还料确认')}}
  if(!valid())return;uncertain.value=false;pendingSubmission=undefined;busy.value=false;visible.value=false;notifyInventoryChanged();emit('saved');
  if(attempt.kind!=='single'){submissionResult.value={...result.data,...(attempt.kind==='outbound'?{direction:'OUT'}:{})};submittedDetail.value=undefined;submissionResultVisible.value=true}
  else{ElMessage.success(result.flowId?'已提交待确认，实物库存尚未变动':'单据已生效');if(result.flowId)emit('flow-created',String(result.flowId));if(completionId)emit('complete-batch',completionId)}
 }catch(e:any){if(valid()){uncertain.value=typeof e?.code!=='number';if(!uncertain.value){pendingSubmission=undefined;const field=e?.fieldErrors?.find((f:Row)=>/^groups\[\d+\]/.test(f.field));const index=Number(field?.field?.match(/^groups\[(\d+)\]/)?.[1]),group=inboundGroups.value[index];if(group){busy.value=false;activateInboundGroup(group.warehouseId)}}outboundErrors.value=e?.fieldErrors??[];inboundError.value=uncertain.value?'提交结果未知，请重试原请求确认结果；全部输入已保留。':userMessage(e?.message,'保存失败，请核对当前信息后重试');if(!uncertain.value&&/版本|刷新|重新加载/.test(inboundError.value))needsReview.value=true;applyFieldErrors(headerForm.value,e)}}finally{if(!disposed&&formSessionCurrent()&&session===openEpoch)busy.value=false}
}

async function openNextStep(context:Row){
 await open('OUT');if(disposed||!visible.value)return;const session=openEpoch;
 if(String(form.factoryId)!==String(context.factoryId))await changeFactory(String(context.factoryId));
 if(disposed||session!==openEpoch||!visible.value)return;
 form.workOrderId=String(context.workOrderId);await orderChanged();
 if(disposed||session!==openEpoch||!visible.value||!items.value.some(i=>String(i.id)===String(context.itemId)))return;
 itemId.value=String(context.itemId);if(!steps.value.some((s:Row)=>String(s.processId)===String(context.processId))){ElMessage.warning('下一工序不可用，请重新选择');return}
 processId.value=String(context.processId);processChanged();
}
watch(lineVisible,v=>{if(v){lineQuantityInput.value=undefined;lineForm.value?.clearValidate()}})
watch(visible,v=>{if(v){completedQuantityInput.value=undefined;headerForm.value?.clearValidate()}})
async function recheckDraft(){if(busy.value||uncertain.value)return;const session=openEpoch,factory=form.factoryId,valid=()=>!disposed&&formSessionCurrent()&&visible.value&&session===openEpoch&&factory===form.factoryId;loading.value=true;try{const data=await fetchOptions(factory,opening.value,form.type,valid);if(!valid())return;publishOptions(data);if(form.workOrderId){const r=await warehouseWorkOrderContext(factory,form.workOrderId,valid);if(!valid())return;workBaseline=JSON.stringify(r.data)}needsReview.value=false;refreshError.value='';ElMessage.info('已重新读取候选，请核对库存、额度及当前输入后再确认')}catch(e:any){if(valid())refreshError.value=e.message}finally{if(valid())loading.value=false}}
const {failed:refreshFailed}=useInventoryRefresh(async()=>{},computed(()=>true),{allowed:()=>visible.value&&(can('metal:warehouse-order:add')||opening.value&&can('metal:inventory:add')),reset:()=>{if(visible.value)invalidateFormSession()}},{paused:computed(()=>busy.value||dependenciesLoading.value||checkingStock.value||refreshingReturn.value||uncertain.value),probe:async ctx=>{if(!form.factoryId)return;const session=openEpoch,factory=form.factoryId,type=form.type,work=form.workOrderId,valid=()=>ctx.isCurrent()&&!disposed&&formSessionCurrent()&&visible.value&&session===openEpoch&&factory===form.factoryId&&type===form.type&&work===form.workOrderId&&!busy.value&&!dependenciesLoading.value&&!checkingStock.value&&!refreshingReturn.value&&!uncertain.value;const data=await fetchOptions(factory,opening.value,type,valid,true);if(!valid())return;let changed=JSON.stringify(data)!==optionsBaseline;if(work){const r=await warehouseWorkOrderContext(factory,work,valid,true);changed=changed||JSON.stringify(r.data)!==workBaseline}if(valid()&&changed){needsReview.value=true;refreshError.value='业务资料已更新，请重新核对候选、库存与额度；当前输入已保留。'}}})
onBeforeRouteLeave(()=>{if(busy.value||uncertain.value||customerBlocked.value)return false;cancelOpen()});onBeforeRouteUpdate(()=>{if(busy.value||uncertain.value||customerBlocked.value)return false;cancelOpen()})
defineExpose({open,cancelOpen,openNextStep,isOpen:computed(()=>visible.value||lineVisible.value)})
</script>
